// 双亲委派的典型实现（简化）
protected Class<?> loadClass(String name, boolean resolve) {
    Class<?> c = findLoadedClass(name);      // 1. 已加载过就直接返回
    if (c == null) {
        try { c = parent.loadClass(name, false); }  // 2. 先委派父加载器
        catch (ClassNotFoundException e) { c = findClass(name); }  // 3. 父加载失败才自己加载
    }
    return c;
}

