  }
  private void setUpNetworking() {
    try {
      InetSocketAddress serverAddress = new InetSocketAddress("127.0.0.1", 5000);
      SocketChannel socketChannel = SocketChannel.open(serverAddress);
      writer = new PrintWriter(Channels.newWriter(socketChannel, UTF_8)); // 造桥+链
    } catch (IOException e) { e.printStackTrace(); }
  }
  private void sendMessage() {
    writer.println(outgoing.getText());  // println 带换行，配对读端 readLine
    writer.flush();                       // 立刻送出
    outgoing.setText("");                 // 清空输入框
    outgoing.requestFocus();              // 焦点还给它
  }
}

// Ready-Bake 聊天服务器的关键结构
private final List<PrintWriter> clientWriters = new ArrayList<>();  // 所有客户端的写入器
public void go() {
  ExecutorService threadPool = Executors.newCachedThreadPool();
  ServerSocketChannel serverSocketChannel = ServerSocketChannel.open();
  serverSocketChannel.bind(new InetSocketAddress(5000));
  while (serverSocketChannel.isOpen()) {
    SocketChannel clientSocket = serverSocketChannel.accept();      // 阻塞等连接
    PrintWriter writer = new PrintWriter(Channels.newWriter(clientSocket, UTF_8));
    clientWriters.add(writer);                                      // 登记，供广播用
    threadPool.submit(new ClientHandler(clientSocket));             // 每个客户端一个线程！
  }
}
private void tellEveryone(String message) {
  for (PrintWriter writer : clientWriters) { writer.println(message); writer.flush(); }
} // 广播给所有人，包括发送者自己

